import { addRacks, getRacksDetail } from "@/api/device/resoureracks";
import { getDictList as _getDictList } from "@/api/dict";
import xtTreeLzaySelect from "@/components/xtTreeLzaySelect/index.vue";
import { getDeptList as _getDeptList } from "@/api/system/dept";
export default {
  name: "racksAddOrUpdate",
  components: {
    xtTreeLzaySelect: xtTreeLzaySelect
  },
  data: function data() {
    return {
      runningStatusList: [],
      racksOccupancyList: [],
      maintenanceFactoryList: [],
      form: {},
      unitList: []
    };
  },
  created: function created() {
    var _this = this;
    //获取 部门列表
    this.getDeptList();
    //字典加载
    this.getDictList("maintenanceFactory");
    this.getDictList("yesNo");
    this.getDictList("cabinets_status");
    this.form.belongRacks = this.$route.query.cabinetsName;
    if (this.$route.query.showType === '修改') {
      getRacksDetail(this.$route.query.id).then(function (res) {
        _this.form = res.data;
      });
    }
  },
  methods: {
    getDeptList: function getDeptList() {
      var _this2 = this;
      //获取部门 单位
      _getDeptList().then(function (res) {
        _this2.unitList = res.data;
      });
    },
    getEntityUnit: function getEntityUnit(val) {
      //选择领用单位 部门
      this.form.maintenanceUnit = val.fullName;
      this.$refs.dataForm.$forceUpdate();
      this.$forceUpdate();
    },
    getDictList: function getDictList(code) {
      var _this3 = this;
      _getDictList(code).then(function (res) {
        if (code === "maintenanceFactory") {
          _this3.maintenanceFactoryList = res.data;
        } else if (code === "yesNo") {
          _this3.racksOccupancyList = res.data;
        } else if (code === "cabinets_status") {
          _this3.runningStatusList = res.data;
        }
      });
    },
    submitReset: function submitReset() {
      this.$closePage('/assets/comdevManage');
    },
    onSubmit: function onSubmit() {
      var _this4 = this;
      var cabinetsId = this.$route.query.cabinetsId;
      this.form.cabinetsId = cabinetsId;
      addRacks(this.form).then(function (res) {
        _this4.$message({
          type: "success",
          message: "操作成功!"
        });
        var handleType = '';
        if (_this4.$route.query.showType === "修改") handleType = '修改';else handleType = '新增';
        res.data.title = res.data.racksName;
        _this4.$store.commit('SET_LIST_UPDATE', new Date().getTime());
        _this4.$store.commit('SET_UPDATE_FORM', {
          handleType: handleType,
          dataType: 'racks',
          nodeDetail: res.data
        });
        _this4.submitReset();
      }, function (error) {});
    },
    changeUseDate: function changeUseDate(val) {
      if (val != null && this.form.returnDate && this.form.returnDate != null) {
        if (new Date(val).getTime() > new Date(this.form.returnDate).getTime()) {
          this.$message({
            type: "warning",
            message: "投运日期不可大于退运日期!"
          });
          this.form.useDate = null;
        }
      }
    },
    changeReturnDate: function changeReturnDate(val) {
      if (val != null && this.form.useDate && this.form.useDate != null) {
        if (new Date(val).getTime() < new Date(this.form.useDate).getTime()) {
          this.$message({
            type: "warning",
            message: "退运日期不可小于投运日期!"
          });
          this.form.returnDate = null;
        }
      }
    }
  }
};
